// AUTO-GENERATED — bundled default Apple Wallet pass art: base64 of each PNG in
// models/loyalty.pass/ (same files as assets/), at the BUILD_PLAN §3 sizes.
// These guarantee a merchant with no uploaded branding still issues a VALID
// pass (Apple requires icon.png). Decoded to Buffers at runtime so there is
// NO disk read (Vercel file-tracing safe) — do NOT read models/ at runtime.

const DEFAULT_ASSETS_B64: Record<string, string> = {
  "icon.png": "",
  "icon@2x.png": "",
  "icon@3x.png": "",
  "logo.png": "",
  "logo@2x.png": "",
  "logo@3x.png": "",
  "strip.png": "",
  "strip@2x.png": "",
  "strip@3x.png": "",
};

const cache = new Map<string, Buffer>();

/** Bundled default art for a pass asset filename, or undefined if none. */
export function defaultAssetBuffer(name: string): Buffer | undefined {
  const b64 = DEFAULT_ASSETS_B64[name];
  if (!b64) return undefined;
  let buf = cache.get(name);
  if (!buf) {
    buf = Buffer.from(b64, "base64");
    cache.set(name, buf);
  }
  return buf;
}

/** Filenames that have a bundled default (used to assemble the buffer map). */
export const DEFAULT_ASSET_NAMES = Object.keys(DEFAULT_ASSETS_B64);
